// AgentCursor3D.js — the custom cursor for /myspace.
//
// It keeps the familiar arrow you already know how to aim, built as a chunky
// extruded 3D object that banks in perspective as you move, trailed by a soft
// blob that squashes along its direction of travel.
//
// The interactive part is magnetism: over anything clickable the blob leaves
// the pointer and snaps to the element's own bounds and corner radius, so the
// cursor reads as gripping the button rather than sitting on top of it.
//
// Perf contract: one rAF loop that puts itself to sleep the moment nothing is
// moving, no per-frame filters, no per-frame layout reads.
import React, { useEffect, useRef, useState } from "react";
import { supportsCustomCursor } from "./pointerCapability";
import "./AgentCursor3D.css";

const clamp = (v, min, max) => Math.max(min, Math.min(max, v));

// The familiar arrow silhouette, drawn big (28×30 instead of the OS's ~16px)
// with its tip at 3,2 so the hotspot lands where the pointer actually is.
const ARROW = "M3 2 L3 25 L9.2 19.4 L13.4 28 L17.6 26 L13.6 17.8 L22 17.2 Z";
// A sliver down the lit edge — the one highlight that sells the bevel.
const GLOSS = "M5 5.4 L5 18.6 L9 14.9 Z";

export default function AgentCursor3D() {
  const [enabled, setEnabled] = useState(false);
  const [label, setLabel] = useState("");

  const layerRef = useRef(null);
  const arrowRef = useRef(null);
  const tiltRef = useRef(null);
  const blobRef = useRef(null);

  useEffect(() => {
    if (supportsCustomCursor()) setEnabled(true);
  }, []);

  useEffect(() => {
    if (!enabled) return undefined;

    const layer = layerRef.current;
    const arrow = arrowRef.current;
    const tilt = tiltRef.current;
    const blob = blobRef.current;
    if (!layer || !arrow || !tilt || !blob) return undefined;

    const root = document.documentElement;
    root.classList.add("ash-bot-cursor");

    const cx = window.innerWidth / 2;
    const cy = window.innerHeight / 2;
    const s = {
      tx: cx,
      ty: cy,
      ax: cx,
      ay: cy,
      bx: cx,
      by: cy,
      pbx: cx,
      pby: cy,
      seen: false,
    };

    let raf = null;
    let awake = false;
    let paused = false;
    let labelEl = null;

    // ---- Magnetism ----
    // While magnetised the blob is driven by the target's rect rather than by
    // the pointer, and CSS owns the transition between the two states.
    let magnetEl = null;
    let unmagnetTimer = null;

    const applyMagnet = () => {
      if (!magnetEl) return;
      const r = magnetEl.getBoundingClientRect();
      const radius =
        parseFloat(getComputedStyle(magnetEl).borderRadius) || r.height / 2;
      blob.style.width = `${r.width + 14}px`;
      blob.style.height = `${r.height + 14}px`;
      blob.style.borderRadius = `${Math.min(radius + 7, 999)}px`;
      blob.style.transform = `translate3d(${r.left + r.width / 2}px, ${
        r.top + r.height / 2
      }px, 0) translate(-50%, -50%)`;
    };

    const setMagnet = (el) => {
      magnetEl = el;
      clearTimeout(unmagnetTimer);
      layer.classList.add("ash-cur3-magnetised");
      applyMagnet();
    };

    const clearMagnet = () => {
      if (!magnetEl) return;
      magnetEl = null;
      blob.style.width = "";
      blob.style.height = "";
      blob.style.borderRadius = "";
      // Keep the eased transition alive just long enough for the blob to fly
      // back to the pointer, then hand control back to the raw rAF writes.
      clearTimeout(unmagnetTimer);
      unmagnetTimer = setTimeout(
        () => layer.classList.remove("ash-cur3-magnetised"),
        340
      );
      wake();
    };

    const wake = () => {
      if (awake || paused) return;
      awake = true;
      raf = requestAnimationFrame(frame);
    };

    const frame = () => {
      raf = null;

      // The arrow is lightly smoothed rather than pinned — enough to feel
      // weighted, not enough to miss what you're aiming at.
      s.ax += (s.tx - s.ax) * 0.42;
      s.ay += (s.ty - s.ay) * 0.42;

      s.pbx = s.bx;
      s.pby = s.by;
      s.bx += (s.tx - s.bx) * 0.13;
      s.by += (s.ty - s.by) * 0.13;

      const vx = s.bx - s.pbx;
      const vy = s.by - s.pby;
      const speed = Math.hypot(vx, vy);

      // Bank the arrow in perspective, tipping away from the direction of
      // travel the way a held object would.
      const rotY = clamp(vx * 1.5, -26, 26);
      const rotX = clamp(-vy * 1.5, -26, 26);
      const lift = clamp(speed * 0.35, 0, 7);

      // Squash the blob along its heading. This is the whole "fluid" read:
      // a circle at rest, an ellipse smeared into the movement.
      const stretch = clamp(speed * 0.028, 0, 0.42);
      const angle = speed > 0.4 ? (Math.atan2(vy, vx) * 180) / Math.PI : 0;

      // A magnetised blob is parked by CSS, not by this loop, so it must not
      // hold the loop awake — otherwise resting on a button spins rAF forever.
      const arrowGap = Math.abs(s.tx - s.ax) + Math.abs(s.ty - s.ay);
      const blobGap = magnetEl
        ? 0
        : Math.abs(s.tx - s.bx) + Math.abs(s.ty - s.by);
      const done = arrowGap + blobGap < 0.25;
      if (done) {
        s.ax = s.tx;
        s.ay = s.ty;
        s.bx = s.tx;
        s.by = s.ty;
      }

      arrow.style.transform = `translate3d(${s.ax}px, ${s.ay}px, 0)`;
      tilt.style.transform = `rotateX(${done ? 0 : rotX}deg) rotateY(${
        done ? 0 : rotY
      }deg) translateZ(${done ? 0 : lift}px)`;

      if (!magnetEl) {
        blob.style.transform =
          `translate3d(${s.bx}px, ${s.by}px, 0) translate(-50%, -50%) ` +
          `rotate(${angle}deg) scale(${1 + stretch}, ${1 - stretch * 0.62})`;
      }

      if (labelEl) {
        labelEl.style.transform = `translate3d(${s.ax}px, ${s.ay}px, 0)`;
      }

      if (done) {
        awake = false;
        return;
      }
      raf = requestAnimationFrame(frame);
    };
    wake();

    const onMove = (e) => {
      s.tx = e.clientX;
      s.ty = e.clientY;
      if (!s.seen) {
        s.seen = true;
        s.ax = s.bx = s.pbx = e.clientX;
        s.ay = s.by = s.pby = e.clientY;
        layer.classList.add("ash-cur3-on");
      }
      wake();
    };

    const onOut = (e) => {
      if (!e.relatedTarget && !e.toElement) {
        layer.classList.remove("ash-cur3-on");
      }
    };
    const onOver = () => {
      if (s.seen) layer.classList.add("ash-cur3-on");
    };

    let lastTarget = null;
    const onMouseOver = (e) => {
      const el =
        e.target instanceof Element
          ? e.target.closest('[data-cursor], a, button, [role="button"]')
          : null;
      if (el === lastTarget) return;
      lastTarget = el;

      layer.classList.toggle("ash-cur3-hot", !!el);
      setLabel((el && el.getAttribute("data-cursor")) || "");

      // Only magnetise to things small enough that wrapping them reads as a
      // grip. Snapping the blob around a whole card looks like a selection box.
      if (el) {
        const r = el.getBoundingClientRect();
        if (r.width <= 320 && r.height <= 120) setMagnet(el);
        else clearMagnet();
      } else {
        clearMagnet();
      }

      const tinted =
        e.target instanceof Element
          ? e.target.closest("[style*='--ash-a'], [style*='--ash-hue']")
          : null;
      const hue = tinted
        ? getComputedStyle(tinted).getPropertyValue("--ash-a").trim() ||
          getComputedStyle(tinted).getPropertyValue("--ash-hue").trim()
        : "";
      if (hue) layer.style.setProperty("--ash-cur-hue", hue);
      else layer.style.removeProperty("--ash-cur-hue");
    };

    const onDown = () => layer.classList.add("ash-cur3-down");
    const onUp = () => layer.classList.remove("ash-cur3-down");

    // A magnetised blob is pinned to an element, so it has to ride the scroll.
    // Costs one rect read per frame, and only while actually gripping something.
    let scrollRaf = null;
    const onScroll = () => {
      if (!magnetEl || scrollRaf) return;
      scrollRaf = requestAnimationFrame(() => {
        scrollRaf = null;
        applyMagnet();
      });
    };

    const onVisibility = () => {
      paused = document.hidden;
      if (paused) {
        if (raf) cancelAnimationFrame(raf);
        raf = null;
        awake = false;
      } else {
        wake();
      }
    };

    const syncLabelEl = () => {
      labelEl = layer.querySelector(".ash-cur3-label");
      if (labelEl) {
        labelEl.style.transform = `translate3d(${s.ax}px, ${s.ay}px, 0)`;
      }
    };
    const labelObserver = new MutationObserver(syncLabelEl);
    labelObserver.observe(layer, { childList: true });
    syncLabelEl();

    window.addEventListener("mousemove", onMove, { passive: true });
    window.addEventListener("mouseover", onMouseOver, { passive: true });
    document.addEventListener("mouseout", onOut);
    document.addEventListener("mouseover", onOver);
    window.addEventListener("mousedown", onDown);
    window.addEventListener("mouseup", onUp);
    window.addEventListener("scroll", onScroll, { passive: true });
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      paused = true;
      if (raf) cancelAnimationFrame(raf);
      if (scrollRaf) cancelAnimationFrame(scrollRaf);
      clearTimeout(unmagnetTimer);
      labelObserver.disconnect();
      root.classList.remove("ash-bot-cursor");
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseover", onMouseOver);
      document.removeEventListener("mouseout", onOut);
      document.removeEventListener("mouseover", onOver);
      window.removeEventListener("mousedown", onDown);
      window.removeEventListener("mouseup", onUp);
      window.removeEventListener("scroll", onScroll);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [enabled]);

  if (!enabled) return null;

  return (
    <div className="ash-cur3" ref={layerRef} aria-hidden="true">
      {/* Trailing blob — free-floating, or gripped to an element */}
      <div className="ash-cur3-blob" ref={blobRef} />

      {/* The arrow itself, extruded in real 3D space */}
      <div className="ash-cur3-arrow" ref={arrowRef}>
        <div className="ash-cur3-tilt" ref={tiltRef}>
          <svg viewBox="0 0 28 30" className="ash-cur3-svg">
            {/* Stop colours come from CSS classes, not presentation
                attributes — var() isn't resolved in an attribute. */}
            <defs>
              <linearGradient id="ash-cur3-face" x1="0" y1="0" x2="0.7" y2="1">
                <stop offset="0" className="ash-cur3-s0" />
                <stop offset="0.55" className="ash-cur3-s1" />
                <stop offset="1" className="ash-cur3-s2" />
              </linearGradient>
              <linearGradient id="ash-cur3-shine" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" className="ash-cur3-g0" />
                <stop offset="1" className="ash-cur3-g1" />
              </linearGradient>
            </defs>

            {/* Extrusion: the same silhouette stacked and darkened, which is
                what gives the arrow real thickness instead of a flat drop
                shadow. Cheaper than an SVG filter and it rotates correctly. */}
            <g className="ash-cur3-extrude">
              {[3.4, 2.6, 1.8, 1].map((o) => (
                <path
                  key={o}
                  className="ash-cur3-side"
                  d={ARROW}
                  transform={`translate(${o} ${o})`}
                />
              ))}
            </g>

            <path className="ash-cur3-body" d={ARROW} />
            <path className="ash-cur3-gloss" d={GLOSS} />
          </svg>
        </div>
      </div>

      {label ? (
        <div className="ash-cur3-label">
          <span>{label}</span>
        </div>
      ) : null}
    </div>
  );
}
